CREATE TABLE IF NOT EXISTS subcontract_progress_certificates(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,certificate_code VARCHAR(30) NOT NULL,certificate_number VARCHAR(100) NULL,subcontract_id BIGINT UNSIGNED NOT NULL,period_from DATE NULL,period_to DATE NULL,certificate_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',previous_progress_percentage DECIMAL(7,4) NULL,current_progress_percentage DECIMAL(7,4) NULL,cumulative_progress_percentage DECIMAL(7,4) NULL,previous_earned_value DECIMAL(18,2) NULL,current_earned_value DECIMAL(18,2) NULL,cumulative_earned_value DECIMAL(18,2) NULL,approved_at DATETIME NULL,approved_by BIGINT UNSIGNED NULL,cancelled_at DATETIME NULL,cancelled_by BIGINT UNSIGNED NULL,notes TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_subcontract_progress_code(certificate_code),UNIQUE KEY uq_subcontract_progress_number(subcontract_id,certificate_number),KEY idx_subcontract_progress_history(subcontract_id,status,certificate_date,id),CONSTRAINT fk_subcontract_progress_subcontract FOREIGN KEY(subcontract_id) REFERENCES subcontracts(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_progress_approved_by FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_progress_cancelled_by FOREIGN KEY(cancelled_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_subcontract_progress_status CHECK(status IN('draft','approved','cancelled')),CONSTRAINT chk_subcontract_progress_period CHECK(period_from IS NULL OR period_to IS NULL OR period_to>=period_from),CONSTRAINT chk_subcontract_progress_percentages CHECK((previous_progress_percentage IS NULL OR(previous_progress_percentage>=0 AND previous_progress_percentage<=100))AND(current_progress_percentage IS NULL OR(current_progress_percentage>=0 AND current_progress_percentage<=100))AND(cumulative_progress_percentage IS NULL OR(cumulative_progress_percentage>=0 AND cumulative_progress_percentage<=100))),CONSTRAINT chk_subcontract_progress_values CHECK((previous_earned_value IS NULL OR previous_earned_value>=0)AND(current_earned_value IS NULL OR current_earned_value>=0)AND(cumulative_earned_value IS NULL OR cumulative_earned_value>=0))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
